INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(53011, 'Job 3:18', 'Job', 3, 18, 'چرته چې قېديان هم په آرام وى، او هغوئ د ظالمانو آواز نۀ اورى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_18.mp3', '', 1761754199, 1761754199),
(53012, 'Job 3:19', 'Job', 3, 19, 'غټ او واړۀ هلته دى، او غلامان د خپلو نېکانو نه آزاد دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_19.mp3', '', 1761754199, 1761754199),
(53013, 'Job 3:20', 'Job', 3, 20, 'چې څوک په مصيبت کښې وى هغه ولې ژوندى پرېږدى، او چې د چا ژوند د غمونو نه ډک وى نو هغۀ له ژوند ولې ورکوى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_20.mp3', '', 1761754199, 1761754199),
(53014, 'Job 3:21', 'Job', 3, 21, 'چې څوک مرګ غواړى، هغۀ له نۀ راځى، هغوئ دا د پټې خزانې نه زيات لټوى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_21.mp3', '', 1761754199, 1761754199),
(53015, 'Job 3:22', 'Job', 3, 22, 'کله چې هغوئ مړۀ شى نو ډېر خوشحاله شى، او چې کله قبر له لاړ شى نو هغوئ خوشحاله شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_22.mp3', '', 1761754199, 1761754199),
(53016, 'Job 3:23', 'Job', 3, 23, 'چې څوک لار نۀ شى ليدلے نو هغۀ له رڼا ولې ورکولے شى، څوک چې خُدائ پاک راګېر کړے وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_23.mp3', '', 1761754199, 1761754199),
(53017, 'Job 3:24', 'Job', 3, 24, 'ځکه چې د روټۍ په ځائ ما ته اسويلى راځى، او زما فريادونه د اوبو په شان تويَولے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_24.mp3', '', 1761754199, 1761754199),
(53018, 'Job 3:25', 'Job', 3, 25, 'چې زۀ د څۀ نه يرېږم نو هغه په ما راځى، او چې د څۀ نه يرېږم نو هغه په ما راغورزيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_25.mp3', '', 1761754199, 1761754199),
(53019, 'Job 3:26', 'Job', 3, 26, 'زۀ په آرام نۀ يم او نۀ زۀ خاموش يم، زۀ پرېشانه يم، خو زما مصيبت نۀ ختميږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_26.mp3', '', 1761754199, 1761754199),
(53020, 'Ezekiel 39:1', 'Ezekiel', 39, 1, 'څښتن وویل: «ای فاني انسانه، د جوج په ضد نبوت وکړه او ووایه چې څښتن تعالی داسې وایي: ‹ای جوجه، د ماشک او توبال د قومونو پاچا، زه ستا دښمن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_1.mp3', '', 1761754199, 1761754199),
(53021, 'Ezekiel 39:2', 'Ezekiel', 39, 2, 'زه به تا د هغې لارې نه چې ته ورباندې روان یې راوګرځوم، راکش به دې کړم او د شمال د ډېر لېرې ځای څخه به دې د اسراییلو غرونو ته د حملې دپاره راولم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_2.mp3', '', 1761754199, 1761754199),
(53022, 'Ezekiel 39:3', 'Ezekiel', 39, 3, 'بیا به دې د چپ لاس نه لینده او ښي لاس نه غشي وغورځوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_3.mp3', '', 1761754199, 1761754199),
(53023, 'Ezekiel 39:4', 'Ezekiel', 39, 4, 'ته، ستا لښکر او ستا ملګري به د اسراییلو په غرونو باندې وژل شوي پراته وي او ستاسو بدنونه به د هر ډول ښکاري مرغانو او وحشي حیواناتو خوراک کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_4.mp3', '', 1761754199, 1761754199),
(53024, 'Ezekiel 39:5', 'Ezekiel', 39, 5, 'تاسو به په صحرا کې مړه پراته یئ. ما څښتن تعالی داسې ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_5.mp3', '', 1761754199, 1761754199),
(53025, 'Ezekiel 39:6', 'Ezekiel', 39, 6, 'زه به په ماجوج او هغو خلکو باندې چې د بحیرې په غاړه او په جزیرو کې په امن کې اوسیږي، اور نازل کړم او هغوی به پوه شي چې زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_6.mp3', '', 1761754199, 1761754199),
(53026, 'Ezekiel 39:7', 'Ezekiel', 39, 7, 'په دې ډول به زما قوم اسراییل زما سپېڅلی نوم وپېژني او نور به پرېنږدم چې زما د نوم سپکاوی وشي. بیا به نور قومونه پوه شي چې زه څښتن د اسراییلو سپېڅلی خدای یم.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_7.mp3', '', 1761754199, 1761754199),
(53027, 'Ezekiel 39:8', 'Ezekiel', 39, 8, 'څښتن تعالی داسې وایي: ‹د کومې ورځې په هکله چې ما خبرې کړې وې، هغه به خامخا راورسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_8.mp3', '', 1761754199, 1761754199),
(53028, 'Ezekiel 39:9', 'Ezekiel', 39, 9, 'کله چې هغه ورځ راشي، نو کوم خلک چې د اسراییلو په ښارونو کې اوسیږي، هغوی به دباندې ووځي او هغوی به هغه وسلې راټولې کړي چې د هغوی د وژل شویو دښمنانو نه پاتې شوې دي. هغوی به سپرونو، لیندو، غشو، ډنډو او نېزو باندې اور بلوي او د اوو کالو دپاره د هغو څخه د سوځېدونکو موادو په توګه کار واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_9.mp3', '', 1761754199, 1761754199),
(53029, 'Ezekiel 39:10', 'Ezekiel', 39, 10, 'هغوی ته به په پټیو کې د سوځولو د لرګیو د راټولولو او په ځنګل کې د ونو د وهلو اړتیا نه وي، ځکه چې د هغوی سره به د سوځولو دپاره پرېمانه وسله وي. هغوی به هغه خلک لوټ او تالا کړي چې دوی یې لوټ او تالا کړي وو. څښتن تعالی داسې ویلي دي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_10.mp3', '', 1761754199, 1761754199),
(53030, 'Ezekiel 39:11', 'Ezekiel', 39, 11, 'څښتن وویل: «کله چې دا ټولې پېښې رامنځته شي، نو زه به جوج ته په اسراییلو کې د مسافرو په دره کې چې د بحیرې په ختیځ کې ده، د هدیرې دپاره ځمکه ورکړم. دا به د مسافرو لاره بنده کړي، ځکه هلته به جوج او د هغه لښکر ښخ کړای شي. هغه دره به د «جوج د لښکرو د درې» په نوم یادیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_11.mp3', '', 1761754199, 1761754199),
(53031, 'Ezekiel 39:12', 'Ezekiel', 39, 12, 'اسراییلیان به په اوو میاشتو کې دا ټول مړي ښخ کړي، په دې ډول به دا هېواد بېرته پاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_12.mp3', '', 1761754199, 1761754199),
(53032, 'Ezekiel 39:13', 'Ezekiel', 39, 13, 'د هغه هېواد ټول خلک به د هغوی په ښخولو کې ګډون وکړي او په کومه ورځ چې زه خپل جلال ښکاره کړم، دا به هغوی ته سرلوړي ور په برخه کړي. ما څښتن تعالی داسې ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_13.mp3', '', 1761754199, 1761754199),
(53033, 'Ezekiel 39:14', 'Ezekiel', 39, 14, 'کله چې اووه میاشتې تېرې شوې، نو یو څو تنه به وټاکل شي چې په دوامداره توګه په ټول هېواد کې وګرځي او د حمله کوونکو پاتې شوي مړي د ځمکې په مخ باندې ولټوي، ترڅو هغه ښخ کړي. په دې ډول به هغه هېواد پاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_14.mp3', '', 1761754199, 1761754199),
(53034, 'Ezekiel 39:15', 'Ezekiel', 39, 15, 'کله چې هغوی په هېواد کې ګرځي او د انسان هډوکي پیدا کړي، د هغو په خوا کې دې نښه ولګوي، ترڅو قبر کېندونکي راشي او هغه د جوج د لښکرو په دره کې ښخ کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_15.mp3', '', 1761754199, 1761754199),
(53035, 'Ezekiel 39:16', 'Ezekiel', 39, 16, 'هغه ځای ته نژدې ښار به د «لښکرو» په نوم ونومول شي. نو په دې ډول به هغه هېواد بیا پاک شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_16.mp3', '', 1761754199, 1761754199),
(53036, 'Ezekiel 39:17', 'Ezekiel', 39, 17, 'څښتن تعالی ماته وویل: «ای فاني انسانه، هر ډول مرغان او ټول وحشي حیوانات راوغواړه او ورته ووایه: ‹د هرې خوا نه راټول شئ او هغه قرباني وخورئ چې ستاسو دپاره یې تیاروم. دا به د اسراییلو په غرونو باندې یو لوی جشن وي او هلته تاسو کولای شئ چې غوښه وخورئ او وینه وڅښئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_17.mp3', '', 1761754199, 1761754199),
(53037, 'Ezekiel 39:18', 'Ezekiel', 39, 18, 'تاسو به د جنګیالیو غوښې وخورئ او د دنیا د واکمنانو وینې به وڅښئ. جنګیاليان به لکه د حیواناتو په شان ووژل شي. هغوی ټول به لکه د باشان د چاغو پسونو، وریو، وزو او غویانو په شان ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_18.mp3', '', 1761754199, 1761754199),
(53038, 'Ezekiel 39:19', 'Ezekiel', 39, 19, 'کله چې زه دا خلک لکه د قربانۍ کولو په شان ووژنم، نو تاسو مرغان او حیوانات به دومره وازګه وخورئ چې ورباندې ماړه شئ او دومره وینه به وڅښئ چې ورباندې نشه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_19.mp3', '', 1761754199, 1761754199),
(53039, 'Ezekiel 39:20', 'Ezekiel', 39, 20, 'زما په دسترخوان باندې چې تاسو هرڅومره کولای شئ د اسونو، سپرو عسکرو، او د هر ډول جنګیالیو غوښې وخورئ او خپل ځانونه ورباندې ماړه کړئ.› څښتن تعالی داسې وایي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_20.mp3', '', 1761754199, 1761754199),
(53040, 'Ezekiel 39:21', 'Ezekiel', 39, 21, 'څښتن وویل: «زه به خپل جلال قومونو ته وښایم او هغوی ټول به وویني چې ما څنګه په خپل قدرت سره جوج او د هغه لښکرو ته سزا ورکړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_21.mp3', '', 1761754199, 1761754199),
(53041, 'Ezekiel 39:22', 'Ezekiel', 39, 22, 'د هماغې ورځې نه به د اسراییلو خلک پوه شي چې زه د هغوی څښتن خدای یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_22.mp3', '', 1761754199, 1761754199),
(53042, 'Ezekiel 39:23', 'Ezekiel', 39, 23, 'نو بیا به نور قومونه پوه شي چې اسراییلیان د خپلو ګناهونو له امله اسیران شول، ځکه چې هغوی زما په وړاندې بې‌وفایي کړې وه. نو ما د هغوی نه خپل مخ واړاوه. هغوی مې بیا پرېښودل چې دښمنان یې ورته ماتې ورکړي او په جنګ کې یې ووژني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_23.mp3', '', 1761754199, 1761754199),
(53043, 'Ezekiel 39:24', 'Ezekiel', 39, 24, 'ما د هغوی سره د هغوی د ناپاکۍ او بدعملۍ سره سم چلند وکړ او د هغوی نه مې خپل مخ واړاوه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_24.mp3', '', 1761754199, 1761754199),
(53044, 'Ezekiel 39:25', 'Ezekiel', 39, 25, 'نو څښتن تعالی داسې وویل: «خو زه به اوس د یعقوب په اولادې یعنې د اسراییلو په خلکو باندې رحم وکړم او هغوی به یوځل بیا نېکمرغه کړم. زه به خپل سپېڅلی نوم وساتم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_25.mp3', '', 1761754199, 1761754199),
(53045, 'Ezekiel 39:26', 'Ezekiel', 39, 26, 'کله چې هغوی یوځل بیا په خپل وطن کې په امن کې واوسیږي، هېڅوک نه شي کولای چې هغوی وځوروي. نو هغوی به په هغه د شرم وړ خیانت چې زما سره یې کړی ؤ، اقرار وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_26.mp3', '', 1761754199, 1761754199),
(53046, 'Ezekiel 39:27', 'Ezekiel', 39, 27, 'کله چې زه خپل قوم د هغوی د دښمنانو د وطنونو نه بېرته راولم او سره راټول یې کړم، نو د هغوی په وسیله به زه قومونو ته وښایم چې زه سپېڅلی یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_27.mp3', '', 1761754199, 1761754199),
(53047, 'Ezekiel 39:28', 'Ezekiel', 39, 28, 'نو بیا به زما قوم پوه شي چې زه د هغوی څښتن خدای یم. هغوی به په دې پوه شي، ځکه چې ما هغوی د اسیرانو په توګه ولېږل او اوس یې راټولوم او بېرته یې خپل وطن ته راولم او د هغوی نه به یو کس هم هلته پاتې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_28.mp3', '', 1761754199, 1761754199),
(53048, 'Ezekiel 39:29', 'Ezekiel', 39, 29, 'زه به د اسراییلو په قوم باندې خپل روح نازل کړم او د هغوی نه به بیا هېڅکله خپل مخ وانه ړوم.› ما څښتن تعالی داسې ویلي دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel39_verse_29.mp3', '', 1761754199, 1761754199),
(53049, 'Ecclesiastes 10:1', 'Ecclesiastes', 10, 1, 'لکه څنګه چې مړه مچان د خوشبویه عطرو بوی خرابوي همدا شان لږ حماقت هم حکمت او شوکت ته زیان رسوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes10_verse_1.mp3', '', 1761754199, 1761754199),
(53050, 'Ecclesiastes 10:2', 'Ecclesiastes', 10, 2, 'د هوښیار سړي زړه هغه د سمې لارې په لور بیایي خو د کم‌عقل سړي زړه هغه د ګمراهۍ په لور بیایي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes10_verse_2.mp3', '', 1761754199, 1761754199),
(53051, 'Ecclesiastes 10:3', 'Ecclesiastes', 10, 3, 'یو کم عقل انسان حتی که په لاره هم روان وي، خو ناپوهه وي او هغه خپل حماقت هرچا ته ښکاره کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes10_verse_3.mp3', '', 1761754199, 1761754199),
(53052, 'Ecclesiastes 10:4', 'Ecclesiastes', 10, 4, 'که حاکم درباندې په قهر شي نو خپل مقام مه پرېږده ځکه چې د لویې خطا په وخت کې نرمه ژبه قهر سړوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes10_verse_4.mp3', '', 1761754199, 1761754199),
(53053, 'Ecclesiastes 10:5', 'Ecclesiastes', 10, 5, 'ما د اسمان لاندې بله بدبختي هم ولیدله. په حقیقت کې، د واکدار له خوا دا غلطي کیږي چې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes10_verse_5.mp3', '', 1761754199, 1761754199),
(53054, 'Ecclesiastes 10:6', 'Ecclesiastes', 10, 6, 'کم عقل سړي لوړو مقامونو ته پورته کیږي خو شتمن سړي په ټیټو مقامونو کې پاتې کیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes10_verse_6.mp3', '', 1761754199, 1761754199),
(53055, 'Ecclesiastes 10:7', 'Ecclesiastes', 10, 7, 'ما لیدلي چې غلامان په اسونو باندې ناست دي خو شهزادګان د غلامانو په شان په پښو باندې روان دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes10_verse_7.mp3', '', 1761754199, 1761754199),
(53056, 'Ecclesiastes 10:8', 'Ecclesiastes', 10, 8, 'څوک چې کنده کیندي نو ښایي په خپله په کې ولویږي او څوک چې دېوال ورانوي نو ښایي مار هغه وچیچي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes10_verse_8.mp3', '', 1761754199, 1761754199),
(53057, 'Ecclesiastes 10:9', 'Ecclesiastes', 10, 9, 'څوک چې له کان نه تیږې راوباسي نو ښایي خپل ځان ټپي کړي او څوک چې لرګي ماتوي نو ښایي خپل ځان ژوبل کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes10_verse_9.mp3', '', 1761754199, 1761754199),
(53058, 'Ecclesiastes 10:10', 'Ecclesiastes', 10, 10, 'که تبر پڅ وي او مزدور هغه تېره نه کړي نو د هغه کارول ډېر زور غواړي خو په حکمت کې ګټه دا وي چې بریالیتوب منځ ته راوړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes10_verse_10.mp3', '', 1761754199, 1761754199),
(53059, 'Ecclesiastes 10:11', 'Ecclesiastes', 10, 11, 'که مار مخکې له منتر ویلو څخه سړی وچیچي نو د مارګیر په منتر ویلو کې ګټه څه وي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes10_verse_11.mp3', '', 1761754199, 1761754199),
(53060, 'Ecclesiastes 10:12', 'Ecclesiastes', 10, 12, 'هوښیار سړي ته د خپلې خولې په خبرو عزت ورکول کیږي خو د کم‌عقل د خولې خبرې د هغه د تباهۍ سبب کیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes10_verse_12.mp3', '', 1761754199, 1761754199),
(53061, 'Ecclesiastes 10:13', 'Ecclesiastes', 10, 13, 'د هغه خوله په حماقت سره خلاصیږي او د خولې خبرې یې په شرارت او جهالت سره ختمیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes10_verse_13.mp3', '', 1761754199, 1761754199),
(53062, 'Ecclesiastes 10:14', 'Ecclesiastes', 10, 14, 'کم عقل سړی ډېر غږیږي خو انسان نه پوهیږي چې راتلونکی به څه ډول وي او څوک هغه ته ویلی شي چې څه به پېښیږي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes10_verse_14.mp3', '', 1761754199, 1761754199),
(53063, 'Ecclesiastes 10:15', 'Ecclesiastes', 10, 15, 'په زیار او زحمت سره کم‌عقل سړی ستړی ستومانه کیږي او هغه نه پوهیږي چې په کومه لاره ښار ته رسیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes10_verse_15.mp3', '', 1761754199, 1761754199),
(53064, 'Ecclesiastes 10:16', 'Ecclesiastes', 10, 16, 'افسوس دې وي په تا ای وطنه کله چې ستا پاچا یو بې‌تجربه او کم‌عقل ځوان وي او ستا شهزادګان په سهار کې په ډېر خوراک او نشو کې ډوب وي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes10_verse_16.mp3', '', 1761754199, 1761754199),
(53065, 'Ecclesiastes 10:17', 'Ecclesiastes', 10, 17, 'بختور یې ای وطنه کله چې ستا پاچا د یو باعزته کورنۍ زوی وي او ستا شهزادګان د خپل طاقت په خاطر په مناسب وخت کې وخوري او له نشو او مستیو نه خپل ځانونه لېرې وساتي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes10_verse_17.mp3', '', 1761754199, 1761754199),
(53066, 'Ecclesiastes 10:18', 'Ecclesiastes', 10, 18, 'د لټۍ له امله د کور چت سوری کیږي او د بېکاره لاسونو له امله بام څڅیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes10_verse_18.mp3', '', 1761754199, 1761754199),
(53067, 'Ecclesiastes 10:19', 'Ecclesiastes', 10, 19, 'خواړه د خندا او خوند دپاره وي او شراب ژوند ته خوشحالي راولي خو پیسې د دواړو دپاره وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes10_verse_19.mp3', '', 1761754199, 1761754199),
(53068, 'Ecclesiastes 10:20', 'Ecclesiastes', 10, 20, 'په خپل زړه کې هم پاچا ته ښکنځلې مه کوه حتی په خپله کوټه کې هم یو شتمن پسې لعنت مه وایه کېدای شي د هوا مرغۍ ستا خبرې هغوی ته ورسوي یا وزر لرونکی مرغه دا الفاظ تکرار کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes10_verse_20.mp3', '', 1761754199, 1761754199),
(53069, 'Isaiah 5:1', 'Isaiah', 5, 1, 'ونیسئ غوږ کله چې دا سندره وایمه زه ده دا سندره زما د دوست په خاطر ده دا سندره د هغه د انګور باغ په هکله زما د دوست ؤ د انګورو یو باغ په حاصلخېزه غونډۍ پروت ؤ دا باغ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_1.mp3', '', 1761754199, 1761754199),
(53070, 'Isaiah 5:2', 'Isaiah', 5, 2, 'ځمکه یې وکیندله پاکه یې له تیږو کړله په کې تاکونه د انګورو یې ډېر ښه وکرل په هغه کې یې کړ جوړ برج د پهرو په کې یې جوړ کړ د انګورو خم بیا یې وکړ انتظار د انګور د پخېدلو خو ټول انګور لا هم تروه وو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_2.mp3', '', 1761754199, 1761754199),
(53071, 'Isaiah 5:3', 'Isaiah', 5, 3, 'نو اوس زما دوست وایي: «ای د اورشلیم او یهودا اوسېدونکو، زما او زما د انګورو د باغ په منځ کې قضاوت وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_3.mp3', '', 1761754199, 1761754199),
(53072, 'Isaiah 5:4', 'Isaiah', 5, 4, 'ایا داسې کوم کار ؤ چې ما د دې باغ دپاره نه وي کړی؟ نو بیا ولې دا تروه انګور خواږه نه شول او نه داسې ښه انګور چې ورته په تمه ومه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_4.mp3', '', 1761754199, 1761754199),
(53073, 'Isaiah 5:5', 'Isaiah', 5, 5, 'زه به اوس درته ووایم چې د خپل د انګورو له باغ سره څه وکړم. زه به هغه د اغزیو کټارې چې ګردچاپېره ورڅخه تاو شوې دي، لېرې کړم، دېوالونه به یې راچپه کړم. هغه به همداسې پرېږدم چې هغه تر پښو لاندې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_5.mp3', '', 1761754199, 1761754199),
(53074, 'Isaiah 5:6', 'Isaiah', 5, 6, 'هغه به پرېږدم چې هرزه بوټي په کې راشنه شي. زه به د انګورو تاکونه اصلاح نه کړم او نه به یې په ځمکه کې رمبی ووهم، هغه به پرېږدم چې له اغزیو او کرکڼو ډک شي. زه به ورېځو ته حکم وکړم چې باران ورباندې ونه وروي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_6.mp3', '', 1761754199, 1761754199),
(53075, 'Isaiah 5:7', 'Isaiah', 5, 7, 'د انګورو باغ دی قوم د اسراییلو د مطلق قادر څښتن د یهودا خلک یې تاکونه د انګورو چې څښتن ایښي وو په ډېره خوشحالۍ خپل باغ کې څښتن لرله د انصاف تمه ترې خو د دې په ځای هغوی قتلونه وکړل هغه لرله د نېکۍ تمه ترې خو د دې په ځای د عدالت دپاره پورته شو فریاد د مظلومانو خلکو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_7.mp3', '', 1761754199, 1761754199),
(53076, 'Isaiah 5:8', 'Isaiah', 5, 8, 'افسوس ستاسو په حال! تاسو نور کورونه او پټي اخلئ چې جایداد مو زیات شي، ترڅو چې نور څوک دلته پاتې نه شي او یوازې تاسو په دې هېواد کې واوسېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_8.mp3', '', 1761754199, 1761754199),
(53077, 'Isaiah 5:9', 'Isaiah', 5, 9, 'ما اورېدلي چې مطلق قادر څښتن وایي: «په رښتیا د دې غټو او ښکلو کورونو نه به کنډوالې جوړې شي او نور به څوک په کې نه اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_9.mp3', '', 1761754199, 1761754199),
(53078, 'Isaiah 5:10', 'Isaiah', 5, 10, 'لس جریبه ځمکه چې د انګورو تاکونه په کې ایښودل شوي وي هغه به یوازې یوه چاټۍ شراب ورکړي. لس منه تخم به یوازې یو من حاصل ورکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_10.mp3', '', 1761754199, 1761754199),
(53079, 'Isaiah 5:11', 'Isaiah', 5, 11, 'افسوس ستاسو په حال! تاسو سهار وختي پاڅېږئ، د شرابو په څښلو پیل کوئ او د شپې تر ناوخته نشه پراته یئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_11.mp3', '', 1761754199, 1761754199),
(53080, 'Isaiah 5:12', 'Isaiah', 5, 12, 'تاسو په محفلونو کې ربابونه، چنګونه، چمبې او شپیلۍ وهئ او شراب څښئ، خو تاسو د څښتن کارونو ته پام نه کوئ او نه پوهېږئ چې هغه څه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_12.mp3', '', 1761754199, 1761754199),
(53081, 'Isaiah 5:13', 'Isaiah', 5, 13, 'نو ځکه تاسو زما قوم به د ناپوهۍ په وجه پردیو هېوادونو ته د اسیرانو په توګه یووړل شئ. ستاسو عزتمن به د لوږې او عام خلک به مو له تندې مړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_13.mp3', '', 1761754199, 1761754199),
(53082, 'Isaiah 5:14', 'Isaiah', 5, 14, 'نو د مړو دنیا په ډېرې اشتها سره خپله خوله خلاصه نیولې ده چې د اورشلیم عزتمن، عادي، مست او شور جوړوونکي خلک ژوندي تېر کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_14.mp3', '', 1761754199, 1761754199),
(53083, 'Isaiah 5:15', 'Isaiah', 5, 15, 'هغوی به ټول ټیټ شي او وبه شرمیږي. مغرور خلک به خوار او ذلیل شي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_15.mp3', '', 1761754199, 1761754199),
(53084, 'Isaiah 5:16', 'Isaiah', 5, 16, 'خو مطلق قادر څښتن خپله لویي د قضاوت په کولو سره څرګندوي. خدای خپل سپېڅلتوب د نېکو کارونو په کولو سره ښکاره کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_16.mp3', '', 1761754199, 1761754199),
(53085, 'Isaiah 5:17', 'Isaiah', 5, 17, 'د ښار په کنډوالو کې به وري واښه خوري او سېرلي به په کې د ځان دپاره څړځایونه پیدا کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_17.mp3', '', 1761754199, 1761754199),
(53086, 'Isaiah 5:18', 'Isaiah', 5, 18, 'افسوس ستاسو په حال، چې د دروغو په مزو مو خپل ګناهونه تړلي دي، لکه څوک چې د غویانو د ګاډۍ په شان خپله بد عملي ځان پسې راکاږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_18.mp3', '', 1761754199, 1761754199),
(53087, 'Isaiah 5:19', 'Isaiah', 5, 19, 'تاسو وایئ: «پرېږده څښتن چې څه غواړي هغه زر تر زره وکړي، ترڅو مونږ وکولای شو هغه وګورو. پرېږده چې د اسراییلو سپېڅلی خدای خپلې نقشې عملي کړي او راځئ وګورو چې د هغه اراده څه ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_19.mp3', '', 1761754199, 1761754199),
(53088, 'Isaiah 5:20', 'Isaiah', 5, 20, 'افسوس ستاسو په حال! تاسو بدو ته ښه او ښو ته بد، تیارې ته رڼا او رڼا ته تیاره، تریخ ته خوږ او خوږ ته تریخ وایئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_20.mp3', '', 1761754199, 1761754199),
(53089, 'Isaiah 5:21', 'Isaiah', 5, 21, 'افسوس ستاسو په حال! تاسو په خپلو سترګو ځان هوښیار ګڼئ او په خپل نظر ځان ځیرک بولئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_21.mp3', '', 1761754199, 1761754199),
(53090, 'Isaiah 5:22', 'Isaiah', 5, 22, 'افسوس ستاسو په حال! تاسو د شرابو د څښلو ماهران یئ! تاسو د شرابو په ګډولو کې تکړه یئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_22.mp3', '', 1761754199, 1761754199),
(53091, 'Isaiah 5:23', 'Isaiah', 5, 23, 'تاسو د رشوت په اخیستلو سره یو مجرم ازادوئ او نه پرېږدئ چې د یو بې ګناه کس سره انصاف وشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_23.mp3', '', 1761754199, 1761754199),
(53092, 'Isaiah 5:24', 'Isaiah', 5, 24, 'نو لکه څنګه چې په اور کې بوس او وچ واښه مړاوي کیږي او سوځیږي، نو ستاسو ریښې به ورستې، ستاسو غوټۍ به وچې شي او باد به یې لېرې یوسي. ځکه چې تاسو د مطلق قادر څښتن شریعت رد کړی او د اسراییلو د سپېڅلي خدای لارښوونو ته مو په سپکه سترګه کتلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_24.mp3', '', 1761754199, 1761754199),
(53093, 'Isaiah 5:25', 'Isaiah', 5, 25, 'نو ځکه څښتن په خپل قوم باندې په قهر دی او خپل لاس یې را اوچت کړی دی چې هغوی ته سزا ورکړي. غرونه به ولړزیږي او د مړو بدنونه به په کوڅو کې لکه د خزلو او چټلیو په شان پراته وي. خو بیاهم د څښتن قهر لا نه دی سوړ شوی، د هغه لاس لا تر اوسه د سزا ورکولو دپاره اوچت دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_25.mp3', '', 1761754199, 1761754199),
(53094, 'Isaiah 5:26', 'Isaiah', 5, 26, 'څښتن هغو قومونو ته چې لېرې پراته دي اشاره ورکوي او هغوی راغواړي. هغوی ته شپېلۍ وهي چې د نړۍ له بل سره راشي. ګورئ! هغوی په منډه منډه را‌ځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_26.mp3', '', 1761754199, 1761754199),
(53095, 'Isaiah 5:27', 'Isaiah', 5, 27, 'د هغوی نه هېڅوک هم نه ستړی کیږي، هېڅوک نه ښوییږي. هغوی ته هېڅکله خوب نه ورځي او نه ویده کیږي. د هغوی کمربند نه سستیږي او د هغوی د څپلیو تسمې نه شلیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_27.mp3', '', 1761754199, 1761754199),
(53096, 'Isaiah 5:28', 'Isaiah', 5, 28, 'د هغوی غشي تېره دي او لیندې یې د ویشتلو دپاره تیارې دي. د هغوی د اسونو سومان لکه د تیږې په شان کلک دي او د هغوی د جنګي ګاډیو ارابې لکه د بوړبوړکۍ په شان تاویږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_28.mp3', '', 1761754199, 1761754199),
(53097, 'Isaiah 5:29', 'Isaiah', 5, 29, 'عسکر د ځوانو زمریانو په شان غړمبیږي، غریږي او ښکار رانیسي او داسې ځای ته یې وړي چې هېڅوک یې ترې نه شي خلاصولی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_29.mp3', '', 1761754199, 1761754199),
(53098, 'Isaiah 5:30', 'Isaiah', 5, 30, 'کله چې هغه ورځ راورسیږي، هغوی به په خپل ښکار باندې وغریږي او اواز به یې لکه د بحیرې د څپو په شان وي. ګورئ! ټول هېواد به تیاره وي، خلک به په تکلیف کې وي او رڼا به د ټینګو ورېځو تر شا وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah5_verse_30.mp3', '', 1761754199, 1761754199),
(53099, 'Isaiah 35:1', 'Isaiah', 35, 1, 'خوشحالي به وکړي صحرا او وچه ځمکه خوشحالي به وکړي دښته او وبه غوړیږي ګلان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah35_verse_1.mp3', '', 1761754199, 1761754199),
(53100, 'Isaiah 35:2', 'Isaiah', 35, 2, 'او هغه ګلان به غوټۍ ونیسي پرېمانه اورېدل کیږي به په دې ځایو کې نارې او د خوشحالۍ سندرې شنه او ښکلې به شي دښته د لبنان د غرو په شان شي حاصلخیزه به د کرمل او شارون د کروندو په شان خلک به وګوري شان او شوکت د څښتن هغوی به وویني لویي زمونږ د خدای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah35_verse_2.mp3', '', 1761754199, 1761754199),
(53101, 'Isaiah 35:3', 'Isaiah', 35, 3, 'ورکړه قوت کمزورو او ستړو لاسونو ته او قوي کړه هغه زنګنونه چې لړزیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah35_verse_3.mp3', '', 1761754199, 1761754199),
(53102, 'Isaiah 35:4', 'Isaiah', 35, 4, 'چې اندېښمن دي څوک، هغوی ته ووايئ: «شئ قوي او مه وېرېږئ ګورئ، راروان دی ستاسو خدای تاسو به وژغوري سزا به ورکړي هغه ستاسو دښمنانو ته او ستاسو بدل به د هغوی نه واخلي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah35_verse_4.mp3', '', 1761754199, 1761754199),
(53103, 'Isaiah 35:5', 'Isaiah', 35, 5, 'په هغه وخت کې به ړانده بینا شي او کاڼه به اوري', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah35_verse_5.mp3', '', 1761754199, 1761754199),
(53104, 'Isaiah 35:6', 'Isaiah', 35, 6, 'وهي ټوپونه به ګوډان لکه هوسۍ په شان څوک چې ګونګیان وي وهي نارې د خوشحالۍ به هغوی په صحرا کې به بهیږي چینې د اوبو او په دښته کې ویالې د اوبو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah35_verse_6.mp3', '', 1761754199, 1761754199),
(53105, 'Isaiah 35:7', 'Isaiah', 35, 7, 'شي به بدلې سوځوونکې شګې د اوبو په ډنډ او وچه ځمکه د اوبو په چینو چې په کوم ځای کې اوسېدل سورلنډیان هلته راشنه به شي واښه او لوخې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah35_verse_7.mp3', '', 1761754199, 1761754199),
(53106, 'Isaiah 35:8', 'Isaiah', 35, 8, 'هلته به خلاصه شي یو لویه لاره چې وي به یې نوم «سپېڅلې لاره» تېر به نه شي ناپاک خلک په دې لار هېڅکله خو غوره قوم د څښتن به په دې لاره قدمونه وهي هرڅوک چې لاړ شي په دې لاره که وي بې عقل هم خو نه به شي بې لارې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah35_verse_8.mp3', '', 1761754199, 1761754199),
(53107, 'Isaiah 35:9', 'Isaiah', 35, 9, 'هلته به نه وي زمریان په دې لار به نه وي داړونکي حیوانات خو چې ازاد کړي دي کوم خلک څښتن هغوی به وکړي په دې لاره سفر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah35_verse_9.mp3', '', 1761754199, 1761754199),
(53108, 'Isaiah 35:10', 'Isaiah', 35, 10, 'هغه خلک چې ازاد کړي دي څښتن په خوشحالۍ سره به ورسیږي اورشلیم ته هغوی او راستانه به شي صهیون ته له سندرو سره د هغوی په سر به وي تلپاتې خوشحالي لکه د تاج په شان د هغوی زړونه به وي ډک له خوشحالۍ نه او شي به خلاص د غم او له خفګانه څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah35_verse_10.mp3', '', 1761754199, 1761754199),
(53109, 'Psalms 37:1', 'Psalms', 37, 1, 'په خاطر د بدکارانو اندېښنه مه کړه څوک چې کړي غلط کارونه بخیلي ورسره مه کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms37_verse_1.mp3', '', 1761754199, 1761754199),
(53110, 'Psalms 37:2', 'Psalms', 37, 2, 'د واښو په شان به دا خلک زر وچ شي داسې به مړاوي شي چې څنګه بوټي شنه وچیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms37_verse_2.mp3', '', 1761754199, 1761754199);